function ensureChecklist(w){if(!S.checklists[w.id]){let ts=(Array.isArray(w.type)?w.type:[w.type]).flatMap(t=>CHECK_TEMPLATES[t]||[]);let seen=new Set();ts=ts.filter(x=>{let k=x[0]+'|'+x[1];if(seen.has(k))return false;seen.add(k);return true});if(!ts.length)ts=CHECK_TEMPLATES.other;S.checklists[w.id]=ts.map(x=>({id:uid(),phase:x[0],name:x[1],note:x[2],done:false,user:'',evidence:'',comment:''}));}return S.checklists[w.id]}
function typeLabel(t){let m=Object.fromEntries((S.workTypes||[]).map(x=>[x.id,x.name]));return (Array.isArray(t)?t:[t]).map(x=>m[x]||x||'عمل').join(' + ')}
function renderChecklist(){let w=S.workorders.find(x=>x.id===clwo.value);if(!w){clbox.innerHTML='<div class="empty">اختر أمر عمل.</div>';return}let a=ensureChecklist(w);let phases=[...new Set(a.map(x=>x.phase))];let old=clphase.value;clphase.innerHTML='<option value="">كل المراحل</option>'+phases.map(p=>`<option value="${esc(p)}">${esc(p)}</option>`).join('');clphase.value=old;let f=clphase.value,r=a.filter(x=>!f||x.phase===f);clbox.innerHTML=`<div class="notice"><b>${esc(w.no)}</b> — ${esc(typeLabel(w.type))} — ${a.filter(x=>x.done).length}/${a.length}</div>`+r.map(x=>`<div class="checkrow"><input type="checkbox" ${x.done?'checked':''} onchange="setCL('${w.id}','${x.id}','done',this.checked)"><div><b>${esc(x.name)}</b><div class="mini">${esc(x.phase)} — ${esc(x.note)}</div><input value="${esc(x.comment||'')}" placeholder="ملاحظات" onchange="setCL('${w.id}','${x.id}','comment',this.value)"></div><select onchange="setCL('${w.id}','${x.id}','user',this.value)"><option value="">المسؤول</option>${S.users.map(u=>`<option value="${u.id}" ${u.id===x.user?'selected':''}>${esc(u.name)}</option>`).join('')}</select><input value="${esc(x.evidence||'')}" placeholder="Evidence / Photo / Video" onchange="setCL('${w.id}','${x.id}','evidence',this.value)"></div>`).join('')}
function setCL(w,c,k,v){let x=(S.checklists[w]||[]).find(z=>z.id===c);if(x)x[k]=v;save();renderChecklist()}
