function go(p){document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));document.getElementById(p).classList.add('active');document.querySelectorAll('.navbtn').forEach(x=>x.classList.remove('active'));let btn=[...document.querySelectorAll('.navbtn')].find(x=>x.getAttribute('onclick')?.includes("go('"+p+"')"));if(btn)btn.classList.add('active');title.textContent=navMap[p];refresh()}
function uid(){return Date.now().toString(36)+Math.random().toString(36).slice(2)}function esc(x){return String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function dateDiffDays(end){if(!end)return Infinity;let d=new Date(end+'T23:59:59');return Math.ceil((d-new Date())/86400000)}
function activePermitForWO(wo){let ps=S.permits.filter(p=>p.wo===wo.id);if(!ps.length)return null;return ps.sort((a,b)=>String((b.renewals?.length?b.renewals[b.renewals.length-1].end:b.end)||'').localeCompare(String((a.renewals?.length?a.renewals[a.renewals.length-1].end:a.end)||'')))[0]}
function permitCurrentEnd(p){if(!p)return '';let r=(p.renewals||[]).filter(x=>x.end).sort((a,b)=>String(a.end).localeCompare(String(b.end)));return r.length?r[r.length-1].end:p.end||''}
function permitDaysLeft(p){return dateDiffDays(permitCurrentEnd(p))}
function permitThreshold(p){return p?.type==='emergency'?5:10}
function permitWarn(p){let d=permitDaysLeft(p);return !!p&&!!permitCurrentEnd(p)&&d>=0&&d<=permitThreshold(p)}
function permitExpired(p){return !!p&&!!permitCurrentEnd(p)&&permitDaysLeft(p)<0}
function permitIcon(wo){let p=activePermitForWO(wo);if(!p)return '';let d=permitDaysLeft(p);let s='';if(permitExpired(p))s+=`<span class="permitAlert expired" title="التصريح منتهٍ">⚠️</span>`;else if(permitWarn(p))s+=`<span class="permitAlert" title="التصريح ينتهي خلال ${d} يوم">⚠️</span>`;if(completionDueWarning(p))s+=`<span class="permitAlert" title="لم يتم طلب الإتمام وباقي ${d} يوم">🟠</span>`;if(p.completionRequested)s+=`<span title="تم طلب الإتمام">✅</span>`;return s}
if(window.pdfjsLib){window.pdfjsLib.GlobalWorkerOptions.workerSrc='assets/vendor/pdf/pdf.worker.min.js';}
function normalizeArabicDigits(t){return String(t||'').replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d));}
function parseDateToken(x){let z=normalizeArabicDigits(x).trim().replace(/[.]/g,'/').replace(/-/g,'/');let m=z.match(/^(\d{1,4})\/(\d{1,2})\/(\d{1,4})$/);if(!m)return '';let a=+m[1],b=+m[2],c=+m[3],day,mon,yr;if(a>=1900){yr=a;mon=b;day=c}else{day=a;mon=b;yr=c<100?2000+c:c}if(yr<1900||mon<1||mon>12||day<1||day>31)return '';return `${yr.toString().padStart(4,'0')}-${mon.toString().padStart(2,'0')}-${day.toString().padStart(2,'0')}`}
function extractPermitData(text){
 let t=normalizeArabicDigits(text||'').replace(/\u200f|\u200e/g,'').replace(/\s+/g,' ').trim();
 const dateTokens=[...t.matchAll(/\b\d{1,4}[\/\-.]\d{1,2}[\/\-.]\d{1,4}\b/g)].map(m=>parseDateToken(m[0])).filter(Boolean);
 const unique=[...new Set(dateTokens)];
 const pick=(patterns)=>{for(const re of patterns){let m=t.match(re);if(m&&m[1])return m[1].trim().replace(/\s{2,}/g,' ')}return ''};
 const number=pick([/(?:رقم\s*التصريح|رتم\s*التصريج|رقم\s*التصريج)\s*[:：-]?\s*([0-9٠-٩]{6,})/i,/\b([0-9]{9,})\b/]);
 const issueDate=pick([/(?:تاريخ\s*الإصدار|تاريخ\s*الاصدار|تاربخ\s*الاصدار)\s*[:：-]?\s*([0-9٠-٩\/\-.]+)/i]);
 const start=pick([/(?:تاريخ\s*بدء\s*العمل|تاريخ\s*بدء|بداية\s*العمل|تاريخ\s*البداية|تاريخ\s*بدء\s*العول)\s*[:：-]?\s*([0-9٠-٩\/\-.]+)/i]);
 const end=pick([/(?:تاريخ\s*انتهاء\s*العمل|تاريخ\s*انتهاء|نهاية\s*العمل|تاريخ\s*النهاية|تاريخ\s*انتساء\s*العول)\s*[:：-]?\s*([0-9٠-٩\/\-.]+)/i]);
 const city=pick([/(?:المحافظة|المدينة)\s*[:：-]?\s*([^،,;|]{2,40})/i]);
 const district=pick([/(?:الأحياء|الحي|الاحياء|الحي)\s*[:：-]?\s*([^،,;|]{2,60})/i]);
 const municipality=pick([/(?:البلدية)\s*[:：-]?\s*([^،,;|]{2,80})/i]);
 const totalLength=pick([/(?:إجمالي\s*الطول|اجمالي\s*الطول)\s*[:：-]?\s*([0-9٠-٩.,]+\s*(?:م|متر|كم|كيلومتر)?)/i]);
 const excavationLength=pick([/(?:طول\s*الحفرة|طول\s*الحفر|طول\s*الحفرة)\s*[:：-]?\s*([0-9٠-٩.,]+\s*(?:م|متر|كم|كيلومتر)?)/i]);
 let streets=pick([/(?:الشوارع|الشارع)\s*[:：-]?\s*([^|;]{2,240})/i]);
 if(!streets){let lines=t.split(/(?=\b(?:البرم|الشرقي|الرئيسي|شارع)\b)/i).filter(x=>/(?:البرم|الشرقي|الرئيسي|شارع)/i.test(x));if(lines.length)streets=lines.slice(0,8).join(' — ').trim()}
 const normDate=x=>x?parseDateToken(x):'';
 const data={number,issueDate:normDate(issueDate),start:normDate(start),end:normDate(end),city,district,municipality,streets,totalLength,excavationLength,allDates:unique};
 // Label-aware extraction first; fallback only when labels are absent.
 if(!data.start&&unique.length) data.start=unique.find(d=>d!==data.issueDate)||unique[0]||'';
 if(!data.end&&unique.length) data.end=unique.slice().reverse().find(d=>d!==data.start&&d!==data.issueDate)||unique[unique.length-1]||'';
 if(!data.issueDate&&unique.length) data.issueDate=unique[0]||'';
 for(const k of ['number','city','district','municipality','streets','totalLength','excavationLength']) if(!data[k]) data[k]='لم يتم التعرف';
 return data;
}
function extractPermitDates(text){let d=extractPermitData(text);return {start:d.start,end:d.end,all:d.allDates}}

async function ocrImageCanvas(canvas){
  if(!window.Tesseract)return '';
  try{
    const ctx=canvas.getContext('2d');
    const img=ctx.getImageData(0,0,canvas.width,canvas.height);
    for(let i=0;i<img.data.length;i+=4){const g=0.299*img.data[i]+0.587*img.data[i+1]+0.114*img.data[i+2];const v=g>185?255:(g<105?0:g);img.data[i]=img.data[i+1]=img.data[i+2]=v;}
    ctx.putImageData(img,0,0);
    const r=await Tesseract.recognize(canvas,'ara+eng',{
      workerPath: 'assets/vendor/tesseract/worker.min.js',
      corePath: 'assets/vendor/tesseract/tesseract-core.wasm.js',
      langPath: 'assets/vendor/tesseract',
      gzip: true,
      logger:m=>{if(m.status==='recognizing text'&&window.permitReadStatus)permitReadStatus.textContent=`جاري قراءة التصريح… ${Math.round((m.progress||0)*100)}%`;},
      tessedit_pageseg_mode:'3'
    });
    return r?.data?.text||'';
  }catch(e){return ''}
}
async function readPermitFile(file){
  if(!file)return {text:'',dates:{start:'',end:''}};
  let text='';
  try{
    if(file.type==='application/pdf'&&window.pdfjsLib){
      const buf=await file.arrayBuffer();
      const pdf=await pdfjsLib.getDocument({data:buf}).promise;
      for(let i=1;i<=pdf.numPages;i++){
        const page=await pdf.getPage(i);
        let tc=await page.getTextContent();
        const direct=tc.items.map(x=>x.str).join(' ');
        text+=' '+direct;
        // Important: many permits are scanned PDFs with no text layer.
        if(direct.trim().length<80){
          const vp=page.getViewport({scale:2.4});
          const canvas=document.createElement('canvas');canvas.width=Math.ceil(vp.width);canvas.height=Math.ceil(vp.height);
          await page.render({canvasContext:canvas.getContext('2d'),viewport:vp}).promise;
          const ocr=await ocrImageCanvas(canvas);text+=' '+ocr;
        }
      }
    } else if(file.type.startsWith('image/')){
      const bmp=await createImageBitmap(file);const maxW=2400,scale=Math.min(3,maxW/bmp.width);const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bmp.width*scale));canvas.height=Math.max(1,Math.round(bmp.height*scale));canvas.getContext('2d').drawImage(bmp,0,0,canvas.width,canvas.height);text=await ocrImageCanvas(canvas);
    } else if(file.type.startsWith('text/')) text=await file.text();
  }catch(e){ }
  return {text,dates:extractPermitDates(text)};
}
function linkPermitToWO(p){let w=S.workorders.find(x=>x.id===p.wo);if(!w)return;if(p.start)w.workStart=p.start;if(p.end)w.permitEnd=p.end;if(p.city&&p.city!=='لم يتم التعرف'&&!w.city)w.city=p.city;if(p.district&&p.district!=='لم يتم التعرف'&&!w.area)w.area=p.district;w.permitNumber=p.number||w.permitNumber||'';w.permitIssueDate=p.issueDate||w.permitIssueDate||'';w.permitStreets=p.streets||w.permitStreets||'';w.permitTotalLength=p.totalLength||w.permitTotalLength||'';w.permitExcavationLength=p.excavationLength||w.permitExcavationLength||'';}
function renderPermitAlerts(){let el=document.getElementById('permitAlerts');if(!el)return;let a=S.workorders.map(w=>({w,p:activePermitForWO(w)})).filter(x=>x.p&&permitWarn(x.p)||x.p&&permitExpired(x.p));el.innerHTML=a.map(x=>{let d=permitDaysLeft(x.p);return `<div class="permitNotice ${permitExpired(x.p)?'danger':'warn'}"><b>⚠️ ${esc(x.w.no)}</b> — ${esc(x.p.number||'تصريح')} — ${permitExpired(x.p)?'منتهٍ':`متبقي ${d} يوم`} — ${esc(permitCurrentEnd(x.p))}<button onclick="openWO('${x.w.id}')">فتح أمر العمل</button></div>`}).join('')||''}
