function isHttpUrl(v){return /^https?:\/\//i.test(String(v||'').trim())}
function locationLabelFromUrl(raw){try{let u=new URL(raw);let q=u.searchParams.get('query')||u.searchParams.get('q')||u.searchParams.get('destination')||'';if(q)return decodeURIComponent(q.replace(/\+/g,' '));if(u.hostname.includes('maps'))return 'موقع على خرائط Google';return u.hostname.replace(/^www\./,'')}catch(e){return ''}}
function parseDecimalCoordinates(value){let t=String(value||'').trim().replace(/[،؛;]/g,',').replace(/[−–—]/g,'-');let m=t.match(/(-?\d{1,2}(?:\.\d+)?)\s*[,\s]+\s*(-?\d{1,3}(?:\.\d+)?)/);if(!m)return null;let lat=Number(m[1]),lng=Number(m[2]);if(!Number.isFinite(lat)||!Number.isFinite(lng)||Math.abs(lat)>90||Math.abs(lng)>180)return null;return {lat,lng}}
function coordsFromMapUrl(value){
  const raw=String(value||'').trim();
  try{
    const u=new URL(raw);
    for(const key of ['query','q','ll','destination','origin']){const q=u.searchParams.get(key);if(q){const c=parseDecimalCoordinates(q);if(c)return c;}}
  }catch(e){}
  let m=raw.match(/@(-?\d{1,3}(?:\.\d+)?)[,\s]+(-?\d{1,3}(?:\.\d+)?)/);
  if(m)return parseDecimalCoordinates(m[1]+','+m[2]);
  m=raw.match(/[?&](?:query|q|ll)=(-?\d{1,3}(?:\.\d+)?)[,%20]+(-?\d{1,3}(?:\.\d+)?)/i);
  if(m)return parseDecimalCoordinates(m[1]+','+m[2]);
  return null;
}
function buildMapUrl(text,city){
  const value=String(text||'').trim(); if(!value)return '';
  const c=parseDecimalCoordinates(value);
  if(c)return `https://www.google.com/maps/search/?api=1&query=${c.lat},${c.lng}`;
  if(isHttpUrl(value))return value;
  const q=[value,String(city||'').trim()].filter(Boolean).join(', ');
  return q?'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(q):'';
}
function syncLocationFromText(){
  const value=String(wloc.value||'').trim();
  if(!value){wlink.value='';return;}
  const c=parseDecimalCoordinates(value);
  if(c){
    const normalized=`${c.lat}, ${c.lng}`;
    const url=`https://www.google.com/maps/search/?api=1&query=${c.lat},${c.lng}`;
    wloc.value=normalized; wlink.value=url; return;
  }
  if(isHttpUrl(value)){
    const cc=coordsFromMapUrl(value);
    if(cc){wloc.value=`${cc.lat}, ${cc.lng}`;wlink.value=`https://www.google.com/maps/search/?api=1&query=${cc.lat},${cc.lng}`;}
    else {wlink.value=value;}
    return;
  }
  wlink.value=buildMapUrl(value,wcity?.value||'');
}
function syncLocationFromLink(){
  const value=String(wlink.value||'').trim();
  if(!value)return;
  const c=coordsFromMapUrl(value);
  if(c){wloc.value=`${c.lat}, ${c.lng}`;wlink.value=`https://www.google.com/maps/search/?api=1&query=${c.lat},${c.lng}`;}
}
