 const d=pick([/(?:تاريخ\s*اعتماد\s*أمر\s*العمل|تاريخ\s*اعتماد\s*الأمر|تاريخ\s*الاعتماد|اعتماد\s*أمر\s*العمل)\s*[:：-]?\s*([0-9٠-٩\/\-.]+)/i]);
