async function saveMaterial(){if(!nc.value.trim())return alert('اكتب كود المادة');if(S.materials.some(m=>m.code===nc.value.trim()))return alert('الكود موجود بالفعل');let img=ni.files[0]?await fileData(ni.files[0]):null;S.materials.push({code:nc.value.trim(),unit:nu.value,description:nd.value,sdms:ns.value,usage:ng.value,catalogPage:null,image:img});save();closeModal()}
function materialEdit(i){let m=S.materials[i];showModal(`<h2>تعديل المادة ${esc(m.code)}</h2><div class="row"><div><label>الكود</label><input id="ec" value="${esc(m.code)}"></div><div><label>الوحدة</label><input id="eu2" value="${esc(m.unit)}"></div><div><label>SDMS</label><input id="esd" value="${esc(m.sdms||'')}"></div></div><label>التوصيف</label><input id="ed" value="${esc(m.description)}"><label>الاستخدام</label><textarea id="euse">${esc(m.usage||'')}</textarea><label>تغيير الصورة</label><input id="ei" type="file" accept="image/*"><div class="actions"><button class="primary" onclick="updateMaterial(${i})">حفظ التعديل</button><button onclick="closeModal()">إلغاء</button></div>`)}
async function updateMaterial(i){let m=S.materials[i];m.code=ec.value.trim();m.unit=eu2.value.trim();m.sdms=esd.value.trim();m.description=ed.value;m.usage=euse.value;if(ei.files[0])m.image=await fileData(ei.files[0]);save();closeModal()}
function materialView(i){let m=S.materials[i];let pdf=m.catalogPage?`<iframe class="pdfbox" src="assets/SEC_CATALOGUE.pdf#page=${m.catalogPage}"></iframe>`:'';showModal(`<h2>${esc(m.code)}</h2><p><b>التوصيف:</b> ${esc(m.description)}</p><p><b>الوحدة:</b> ${esc(m.unit||'—')} &nbsp; <b>SDMS:</b> ${esc(m.sdms||'—')}</p><p><b>الاستخدام:</b> ${esc(m.usage||'—')}</p>${m.image?`<img src="${m.image}" style="max-width:100%;max-height:360px">`:''}${pdf?`<h3>صورة/صفحة المادة من كتالوج SEC</h3>${pdf}`:'<div class="notice">لا توجد صورة مرتبطة بهذا الكود في قاعدة الصور؛ يمكنك رفع صورة للمادة من تعديل المادة.</div>'}<div class="actions"><button onclick="closeModal()">إغلاق</button></div>`)}
async function addIssue(){
 if(!iwo.value)return alert('لا يمكن سحب أي مادة بدون ربطها بأمر عمل');
 if(imat.value==='')return alert('اختر المادة');
 let q=parseFloat(iq.value);if(!q)return alert('أدخل الكمية');
 let voucher={name:'',hash:'',size:0};
 const vf=document.getElementById('ivFile')?.files?.[0];
 if(vf){let buf=await vf.arrayBuffer();let hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',buf))).map(x=>x.toString(16).padStart(2,'0')).join('');await idbPut(hash,vf);voucher={name:vf.name,hash,size:vf.size};}
 S.issues.push({id:uid(),wo:iwo.value,mi:+imat.value,qty:q,voucher:voucher.name||iv.value||'',voucherFile:voucher,date:new Date().toISOString()});
 iq.value=iv.value='';if(document.getElementById('ivFile'))document.getElementById('ivFile').value='';save();renderIssues();
}
function downloadStoredFile(hash,name){if(!hash)return;idbGet(hash).then(b=>{if(!b)return alert('الملف غير موجود في التخزين المحلي');let u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=name||'file';a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)})}
function renderIssues(){let a=S.issues.filter(x=>x.wo===iwo.value);renderIssueControls();ibody.innerHTML=a.map(x=>{let m=S.materials[x.mi];let vf=x.voucherFile?.hash?`<button onclick="downloadStoredFile('${x.voucherFile.hash}','${esc(x.voucherFile.name||x.voucher||'إذن_صرف')}')">📄 ${esc(x.voucherFile.name||x.voucher)}</button>`:esc(x.voucher||'—');return `<tr><td>${esc(m?.code)}</td><td>${esc(m?.description)}</td><td>${esc(m?.unit)}</td><td>${x.qty}</td><td>${vf}</td><td>${new Date(x.date).toLocaleString('ar-EG')}</td></tr>`}).join('')||'<tr><td colspan="6" class="empty">لا يوجد صرف لهذا الأمر</td></tr>'}
function renderFiles(){dbody.innerHTML=S.attachments.flatMap(a=>(a.links||[]).map(l=>`<tr><td>${esc(a.name)}</td><td>${esc(l.category||'—')}</td><td>${esc(woName(l.wo))}</td><td>${(a.size/1024).toFixed(1)} KB</td><td><span class="badge ok">نسخة مخزنة واحدة</span></td><td>${new Date(a.date).toLocaleString('ar-EG')}</td></tr>`)).join('')||'<tr><td colspan="6" class="empty">لا توجد ملفات</td></tr>'}
function csv(name,rows){let s=rows.map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\r\n');let b=new Blob(['\ufeff'+s],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;a.click()}
function exportMaterials(){csv('Materials_Database.csv',[['الكود','الوحدة','التوصيف','SDMS','الاستخدام'],...S.materials.map(m=>[m.code,m.unit,m.description,m.sdms,m.usage])])}
function excelReport(){let w=S.workorders.find(x=>x.id===rwo.value);if(!w)return alert('اختر أمر العمل');let a=S.issues.filter(x=>x.wo===w.id);csv('Material_Report_'+w.no+'.csv',[['ENGINEER ISLAM FOUDA'],['تقرير مواد أمر العمل'],['أمر العمل',w.no],['الوصف',w.desc],['الموقع',w.loc],[],['م','كود المادة','التوصيف','الوحدة','الكمية','التاريخ','إذن الصرف','ملف إذن الصرف'],...a.map((x,i)=>{let m=S.materials[x.mi];return[i+1,m?.code,m?.description,m?.unit,x.qty,new Date(x.date).toLocaleString('ar-EG'),x.voucher,x.voucherFile?.name||'']})])}
function summaryReport(){let w=S.workorders.find(x=>x.id===rwo.value);if(!w)return alert('اختر أمر العمل');csv('WorkOrder_Summary_'+w.no+'.csv',[['ENGINEER ISLAM FOUDA'],['أمر العمل',w.no],['الوصف',w.desc],['الموقع',w.loc],['الإسناد',w.assign],['التنفيذ',w.exec],['تاريخ اعتماد أمر العمل',w.approvalDate||''],['ملف أمر العمل',w.workOrderFile?.name||''],[],['القسم','العدد'],['المهام',S.tasks.filter(x=>x.wo===w.id).length],['التنسيقات',S.coord.filter(x=>x.wo===w.id).length],['السلامة',S.safety.filter(x=>x.wo===w.id).length],['التنفيذ',S.exec.filter(x=>x.wo===w.id).length],['الصرف',S.issues.filter(x=>x.wo===w.id).length]])}
function openWO(id){let w=S.workorders.find(x=>x.id===id);let link=w.locationLink||w.mapUrl||((w.loc||w.city)?'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent([w.loc,w.city].filter(Boolean).join(', ')):'');showModal(`<h2>أمر العمل ${esc(w.no)}</h2><p><b>النوع:</b> ${esc(typeLabel(w.type))} &nbsp; | &nbsp; <b>الحالة:</b> ${esc(w.status)} &nbsp; | &nbsp; <b>الأولوية:</b> ${esc(w.priority)}</p><p><b>الشركة:</b> ${esc(w.company||'—')} &nbsp; <b>المشروع:</b> ${esc(w.project||'—')}</p><p><b>المدينة:</b> ${esc(w.city||'—')} &nbsp; <b>الموقع:</b> ${link?`<a class="link" target="_blank" href="${esc(link)}">${esc(w.loc||'فتح الموقع')}</a>`:esc(w.loc||'—')}</p><p>${esc(w.desc||'')}</p><p><b>تاريخ اعتماد أمر العمل:</b> ${esc(w.approvalDate||'—')} ${w.workOrderFile?.hash?`<button onclick="downloadStoredFile('${w.workOrderFile.hash}','${esc(w.workOrderFile.name||'ملف أمر العمل')}')">📄 ملف أمر العمل</button>`:''}</p><div class="grid"><div class="card">👤 المهام: ${S.tasks.filter(x=>x.wo===id).length}</div><div class="card">🏛️ التنسيقات: ${S.coord.filter(x=>x.wo===id).length}</div><div class="card">🦺 السلامة: ${S.safety.filter(x=>x.wo===id).length}</div><div class="card">🏗️ التنفيذ: ${S.exec.filter(x=>x.wo===id).length}</div><div class="card">📦 الصرف: ${S.issues.filter(x=>x.wo===id).length}</div><div class="card">📸 الملفات: ${S.attachments.filter(a=>(a.links||[]).some(l=>l.wo===id)).length}</div></div><h3>📸 صور وملفات أمر العمل</h3><div id="modalGallery" class="gallery"></div><div class="actions"><button class="primary" onclick="dwo.value='${id}';go('docs');closeModal()">📸 إضافة صور/ملفات</button><button onclick="go('checklists');clwo.value='${id}';closeModal()">✅ Checklist</button><button onclick="closeModal()">إغلاق</button></div>`);renderModalGallery(id)}
async function renderModalGallery(wo){let el=document.getElementById('modalGallery');if(!el)return;let arr=S.attachments.filter(a=>(a.links||[]).some(l=>l.wo===wo));let out=[];for(let a of arr){let b=await idbGet(a.hash);let isImg=a.name.match(/\.(jpg|jpeg|png|gif|webp|bmp)$/i);if(isImg&&b){let u=URL.createObjectURL(b);out.push(`<figure><img src="${u}"><figcaption>${esc(a.name)}<br>${esc((a.links||[]).filter(l=>l.wo===wo).map(l=>l.category).join('، '))}</figcaption></figure>`)}else out.push(`<figure><div style="padding:35px 5px;text-align:center">📄</div><figcaption>${esc(a.name)}</figcaption></figure>`)}el.innerHTML=out.join('')||'<div class="empty">لا توجد مرفقات.</div>'}

function toastMsg(msg){let e=document.getElementById('toast');if(!e)return;e.textContent=msg;e.style.display='block';clearTimeout(window.__toastT);window.__toastT=setTimeout(()=>e.style.display='none',2600)}
function dataHealth(){let duplicateWO=S.workorders.length-new Set(S.workorders.map(w=>String(w.no).trim())).size;let orphanIssues=S.issues.filter(x=>!S.workorders.some(w=>w.id===x.wo)).length;let orphanPermits=S.permits.filter(x=>!S.workorders.some(w=>w.id===x.wo)).length;return {duplicateWO,orphanIssues,orphanPermits}}
function exportFullAudit(){let rows=[['ENGINEER ISLAM FOUDA — DATA AUDIT'],['Generated',new Date().toLocaleString('ar-EG')],[],['Work Orders',S.workorders.length],['Open Tasks',S.tasks.filter(x=>!x.done).length],['Permits',S.permits.length],['Material Issues',S.issues.length],['Unique Attachments',S.attachments.length],[],['WO','Description','Company','City','Status','Permit','Permit End','Completion Requested','Tasks','Files']];S.workorders.forEach(w=>{let p=activePermitForWO(w);rows.push([w.no,w.desc,w.company,w.city,w.status,p?.number||'',permitCurrentEnd(p)||'',p?.completionRequested?'نعم':'لا',S.tasks.filter(t=>t.wo===w.id).length,S.attachments.filter(f=>(f.links||[]).some(l=>l.wo===w.id)).length])});csv('Engineer_Islam_Fouda_Full_Audit.csv',rows)}
function renderHome(){let h=dataHealth();let pa=S.permits.filter(p=>permitWarn(p)||permitExpired(p)).length;let od=S.tasks.filter(t=>!t.done&&t.due&&dateDiffDays(t.due)<0).length;recent.innerHTML=`<div class="statusbar"><span class="pill">⚠️ تصاريح تحتاج متابعة: ${pa}</span><span class="pill">⏰ مهام متأخرة: ${od}</span><span class="pill ${h.duplicateWO||h.orphanIssues||h.orphanPermits?'health-warn':'health-ok'}">🧪 سلامة البيانات: ${h.duplicateWO+h.orphanIssues+h.orphanPermits?'تحتاج مراجعة':'جيدة'}</span><button onclick="exportFullAudit()">📊 تقرير شامل</button></div>`+S.workorders.slice(-6).reverse().map(w=>`<div class="card"><b>${esc(w.no)}</b> — ${esc(w.desc)} <span class="badge">${esc(w.loc)}</span> <button onclick="openWO('${w.id}')">فتح</button></div>`).join('')||'<div class="empty">لا توجد أوامر عمل بعد.</div>'}
function showModal(x){modal.innerHTML=x;modalbg.style.display='flex'}function closeModal(){modalbg.style.display='none'}function backup(){let b=new Blob([JSON.stringify(S)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='Engineer_Islam_Fouda_Backup.json';a.click()}function restoreClick(){restoreFile.click()}function restoreFile(f){if(!f)return;let r=new FileReader();r.onload=()=>{try{let parsed=JSON.parse(r.result);S=(parsed&&parsed.data&&typeof parsed.data==='object'&&!Array.isArray(parsed.data))?parsed.data:parsed;if(typeof window!=='undefined')window.S=S;if(typeof global!=='undefined')global.S=S;save();alert('تم استرجاع النسخة')}catch(e){alert('ملف النسخة غير صحيح')}};r.readAsText(f)}
function refresh(){
  const safe=(fn)=>{try{fn()}catch(e){console.warn('refresh module skipped:',e?.message||e)}};
  safe(()=>fill());safe(()=>counts());safe(()=>renderWO());safe(()=>renderTasks());
  let cb=document.getElementById('cbody');if(cb)safe(()=>recTable('coord',cb));
  let sb=document.getElementById('sbody');if(sb)safe(()=>recTable('safety',sb));
  let eb=document.getElementById('ebody');if(eb)safe(()=>recTable('exec',eb));
  safe(()=>renderMaterials());safe(()=>renderIssues());safe(()=>renderFiles());safe(()=>renderHome());safe(()=>renderUsers());
  if(typeof renderGallery==='function'&&document.getElementById('dwo'))safe(()=>renderGallery());
  safe(()=>renderArchive());safe(()=>renderChecklist());safe(()=>renderPermits());safe(()=>renderPermitAlerts());safe(()=>renderCrews());safe(()=>renderSafetyContacts());safe(()=>syncWorkTypeOptions());
}
S.workorders.forEach(w=>ensureChecklist(w));
if(typeof migrateLegacyFiles==='function'){migrateLegacyFiles().then(()=>refresh()).catch(()=>refresh())}else{refresh()};
setInterval(()=>clock.textContent=new Date().toLocaleString('ar-EG',{dateStyle:'medium',timeStyle:'short'}),1000);


// ===== V13 Professional layer =====
function fmtDate(x){if(!x)return '—';try{return new Date(x).toLocaleDateString('ar-SA')}catch(e){return x}}
function smartTypeLabel(t){return {permit:'تصريح',workorder:'ملف أمر عمل',voucher:'إذن صرف',generic:'مستند عام'}[t]||t}
async function extractTextAny(file){
 if(!file)return '';
 if(file.type==='application/pdf'||/\.pdf$/i.test(file.name)){let r=await readPermitFile(file);return r.text||''}
 if(file.type.startsWith('image/')){let c=document.createElement('canvas'),img=new Image();let u=URL.createObjectURL(file);await new Promise((res,rej)=>{img.onload=res;img.onerror=rej;img.src=u});let scale=Math.min(2.2,2200/Math.max(img.width,img.height));c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);URL.revokeObjectURL(u);return await ocrImageCanvas(c)}
 if(file.type.startsWith('text/')||/\.txt$/i.test(file.name))return await file.text();return ''
}
function extractWorkOrderData(text){let t=normalizeArabicDigits(text||'').replace(/\s+/g,' ');let pick=(arr)=>{for(let re of arr){let m=t.match(re);if(m?.[1])return m[1].trim()}return ''};let dates=[...t.matchAll(/\b\d{1,4}[\/\-.]\d{1,2}[\/\-.]\d{1,4}\b/g)].map(m=>parseDateToken(m[0])).filter(Boolean);return {number:pick([/(?:رقم\s*أمر\s*العمل|أمر\s*العمل|work\s*order)\s*[:：-]?\s*([A-Z0-9\/-]{4,})/i]),approvalDate:parseDateToken(pick([/(?:تاريخ\s*اعتماد\s*أمر\s*العمل|تاريخ\s*الاعتماد|approval\s*date)\s*[:：-]?\s*([0-9\/\-.]+)/i]))||dates[0]||'',description:pick([/(?:الوصف|description)\s*[:：-]?\s*([^|]{3,160})/i]),company:pick([/(?:الشركة|company)\s*[:：-]?\s*([^،,;|]{2,80})/i])}}
function extractVoucherData(text){let t=normalizeArabicDigits(text||'').replace(/\s+/g,' ');let pick=(arr)=>{for(let re of arr){let m=t.match(re);if(m?.[1])return m[1].trim()}return ''};return {voucher:pick([/(?:إذن\s*الصرف|رقم\s*الإذن|issue\s*voucher)\s*[:：-]?\s*([A-Z0-9\/-]{3,})/i]),workOrder:pick([/(?:أمر\s*العمل|work\s*order)\s*[:：-]?\s*([A-Z0-9\/-]{3,})/i]),date:parseDateToken(pick([/(?:التاريخ|date)\s*[:：-]?\s*([0-9\/\-.]+)/i]))}}
function smartFields(type,data){let labels=type==='permit'?{number:'رقم التصريح',issueDate:'تاريخ الإصدار',start:'بداية العمل',end:'نهاية العمل',city:'المدينة',district:'الحي',municipality:'البلدية',streets:'الشوارع',totalLength:'إجمالي الطول',excavationLength:'طول الحفرة'}:type==='workorder'?{number:'رقم أمر العمل',approvalDate:'تاريخ الاعتماد',description:'الوصف',company:'الشركة'}:type==='voucher'?{voucher:'رقم إذن الصرف',workOrder:'أمر العمل',date:'التاريخ'}:{};return Object.entries(labels).map(([k,l])=>`<div><label>${l}</label><input id="sdf_${k}" value="${esc(data[k]||'')}" placeholder="لم يتم التعرف"><span class="confidence ${data[k]&&data[k]!=='لم يتم التعرف'?'good':'review'}">${data[k]&&data[k]!=='لم يتم التعرف'?'تم التعرف':'يحتاج مراجعة'}</span></div>`).join('')}
async function smartReadDocument(){let f=sdFile.files[0];if(!f)return alert('اختر الملف أولاً');sdStatus.textContent='جاري قراءة الملف…';try{let text=await extractTextAny(f),type=sdType.value,data=type==='permit'?extractPermitData(text):type==='workorder'?extractWorkOrderData(text):type==='voucher'?extractVoucherData(text):{};window.__smartCurrent={type,data,text,file:f};sdResult.innerHTML=`<h3>نتيجة القراءة — ${esc(f.name)}</h3><div class="progrid">${smartFields(type,data)}</div><h4>النص المستخرج للمراجعة</h4><div class="docpreview">${esc(text||'لم يتم استخراج نص. يمكنك حفظ الملف فقط أو إدخال البيانات يدويًا.')}</div><div class="actions stickyActions"><button class="primary" onclick="smartApply()">✅ اعتماد وحفظ البيانات</button><button onclick="smartStoreOnly()">📎 حفظ الملف فقط</button></div>`;sdStatus.textContent=text?'تمت القراءة. راجع الحقول قبل الاعتماد.':'لم يتم استخراج نص واضح — لم يتم تخمين أي بيانات.';S.smartReads.unshift({id:uid(),date:new Date().toISOString(),type,file:f.name,wo:sdWO.value,result:text?'تمت القراءة':'يحتاج إدخال يدوي'});S.smartReads=S.smartReads.slice(0,100);save();renderSmartHistory()}catch(e){sdStatus.textContent='تعذر قراءة الملف: '+e.message}}
async function smartStoreOnly(){let c=window.__smartCurrent;if(!c)return;let hash=await sha256(c.file),blob=c.file;await idbPut(hash,blob);let a=S.attachments.find(x=>x.hash===hash);if(!a){a={hash,name:c.file.name,size:c.file.size,date:new Date().toISOString(),links:[]};S.attachments.push(a)}if(sdWO.value&&!a.links.some(x=>x.wo===sdWO.value&&x.category==='مستند ذكي'))a.links.push({wo:sdWO.value,category:'مستند ذكي',date:new Date().toISOString()});save();toastMsg('تم حفظ الملف وربطه بدون تكرار')}
async function smartApply(){let c=window.__smartCurrent;if(!c)return;let d={...c.data};document.querySelectorAll('[id^="sdf_"]').forEach(el=>d[el.id.slice(4)]=el.value.trim());await smartStoreOnly();if(c.type==='permit'){if(!sdWO.value)return alert('اختر أمر العمل لحفظ التصريح');S.permits.push({id:uid(),wo:sdWO.value,type:'execution',number:d.number||'',issueDate:d.issueDate||'',start:d.start||'',end:d.end||'',city:d.city||'',district:d.district||'',municipality:d.municipality||'',streets:d.streets||'',totalLength:d.totalLength||'',excavationLength:d.excavationLength||'',renewals:[],completionRequested:false,extractedText:c.text,fileName:c.file.name});let p=S.permits[S.permits.length-1];linkPermitToWO(p)}else if(c.type==='workorder'){let w=S.workorders.find(x=>x.id===sdWO.value)||S.workorders.find(x=>String(x.no)===String(d.number));if(w){if(d.approvalDate)w.approvalDate=d.approvalDate;if(d.description&&!w.desc)w.desc=d.description;if(d.company&&!w.company)w.company=d.company}else alert('اختر أمر العمل الموجود أولاً لتطبيق البيانات.')}save();toastMsg('تم اعتماد البيانات وحفظها')}
function renderSmartHistory(){if(!window.sdHistory)return;sdHistory.innerHTML=(S.smartReads||[]).map(x=>`<tr><td>${new Date(x.date).toLocaleString('ar-SA')}</td><td>${esc(smartTypeLabel(x.type))}</td><td>${esc(x.file)}</td><td>${esc(woName(x.wo)||'—')}</td><td>${esc(x.result)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">لا توجد عمليات قراءة بعد.</td></tr>'}
function workOrderCompletion(w){let cl=ensureChecklist(w),done=cl.filter(x=>x.done).length;return cl.length?Math.round(done/cl.length*100):0}
function buildReportRows(){let w=S.workorders.find(x=>x.id===rwo.value),type=reportType.value,from=reportFrom.value,to=reportTo.value,inside=d=>!d||((!from||d>=from)&&(!to||d<=to));if(type==='materials'){let a=S.issues.filter(x=>(!w||x.wo===w.id)&&inside((x.date||'').slice(0,10)));return [['أمر العمل','الكود','التوصيف','الوحدة','الكمية','إذن الصرف','ملف الإذن','التاريخ'],...a.map(x=>{let m=S.materials[x.mi];return[woName(x.wo),m?.code||'',m?.description||'',m?.unit||'',x.qty,x.voucher||'',x.voucherFile?.name||'',x.date||'']})]}if(type==='permits'){let a=S.permits.filter(x=>(!w||x.wo===w.id)&&inside(x.start));return [['أمر العمل','رقم التصريح','النوع','الإصدار','البداية','النهاية الحالية','المدينة','الحي','البلدية','الشوارع','إجمالي الطول','طول الحفرة','الإتمام'],...a.map(p=>[woName(p.wo),p.number,p.type,p.issueDate,p.start,permitCurrentEnd(p),p.city,p.district,p.municipality,p.streets,p.totalLength,p.excavationLength,p.completionRequested?'تم':'لم يتم'])]}if(type==='tasks'){let a=S.tasks.filter(x=>(!w||x.wo===w.id)&&inside(x.due));return [['المهمة','المسؤول','أمر العمل','الاستحقاق','الحالة'],...a.map(x=>[x.title||x.task||'',x.user||'',woName(x.wo),x.due||'',x.done?'مكتمل':'مفتوح'])]}if(type==='evidence'){let a=S.attachments.flatMap(f=>(f.links||[]).filter(l=>!w||l.wo===w.id).map(l=>[woName(l.wo),l.category,f.name,(f.size/1024).toFixed(1)+' KB',f.date]));return [['أمر العمل','القسم','الملف','الحجم','التاريخ'],...a]}if(type==='audit'){return [['المؤشر','القيمة'],['أوامر العمل',S.workorders.length],['المهام المفتوحة',S.tasks.filter(x=>!x.done).length],['التصاريح',S.permits.length],['سحوبات المواد',S.issues.length],['الملفات الفريدة',S.attachments.length],['ملفات القراءة الذكية',(S.smartReads||[]).length]]}if(w){let p=activePermitForWO(w);return [['ENGINEER ISLAM FOUDA'],['ملف أمر العمل الشامل'],['رقم الأمر',w.no],['الوصف',w.desc],['الشركة',w.company],['المشروع',w.project],['المدينة',w.city],['الموقع',w.loc],['تاريخ الإسناد',w.assign],['تاريخ التنفيذ',w.exec],['تاريخ الاعتماد',w.approvalDate||''],['الحالة',w.status],['نسبة إنجاز Checklist',workOrderCompletion(w)+'%'],['التصريح',p?.number||''],['نهاية التصريح',permitCurrentEnd(p)||''],['المهام',S.tasks.filter(x=>x.wo===w.id).length],['التنسيقات',S.coord.filter(x=>x.wo===w.id).length],['السلامة',S.safety.filter(x=>x.wo===w.id).length],['التنفيذ',S.exec.filter(x=>x.wo===w.id).length],['سحوبات المواد',S.issues.filter(x=>x.wo===w.id).length],['الملفات',S.attachments.filter(f=>(f.links||[]).some(l=>l.wo===w.id)).length]]}return [['اختر أمر عمل للتقرير الشامل']]}
function generateDynamicReport(){let rows=buildReportRows();reportPreview.innerHTML=`<div class="tablewrap"><table>${rows.map((r,i)=>`<tr>${r.map(c=>i===0?`<th>${esc(c)}</th>`:`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</table></div>`}
function exportDynamicReport(){let rows=buildReportRows(),w=S.workorders.find(x=>x.id===rwo.value);csv(`Report_${reportType.value}_${w?.no||'ALL'}.csv`,rows)}
function editWO(id){let w=S.workorders.find(x=>x.id===id);if(!w)return;showModal(`<h2>تعديل أمر العمل ${esc(w.no)}</h2><div class="progrid"><div><label>الوصف</label><input id="ewDesc" value="${esc(w.desc||'')}"></div><div><label>الشركة</label><input id="ewCompany" value="${esc(w.company||'')}"></div><div><label>المشروع</label><input id="ewProject" value="${esc(w.project||'')}"></div><div><label>المدينة</label><input id="ewCity" value="${esc(w.city||'')}"></div><div><label>الحي</label><input id="ewArea" value="${esc(w.area||'')}"></div><div><label>الحالة</label><select id="ewStatus">${['جديد','قيد التنفيذ','مكتمل','معلق','ملغي'].map(x=>`<option ${x===w.status?'selected':''}>${x}</option>`).join('')}</select></div><div><label>الأولوية</label><select id="ewPriority">${['عادي','عاجل','حرج'].map(x=>`<option ${x===w.priority?'selected':''}>${x}</option>`).join('')}</select></div><div><label>المسؤول</label><input id="ewAssigned" value="${esc(w.assignedTo||'')}"></div></div><div class="actions"><button class="primary" onclick="saveWOEdit('${id}')">حفظ التعديل</button><button onclick="closeModal()">إلغاء</button></div>`)}
function saveWOEdit(id){let w=S.workorders.find(x=>x.id===id);if(!w)return;w.desc=ewDesc.value;w.company=ewCompany.value;w.project=ewProject.value;w.city=ewCity.value;w.area=ewArea.value;w.status=ewStatus.value;w.priority=ewPriority.value;w.assignedTo=ewAssigned.value;save();closeModal();toastMsg('تم تعديل أمر العمل')}
// decorate existing WO modal with edit action
const __openWO_V12=openWO;openWO=function(id){__openWO_V12(id);let a=document.querySelector('#modal .actions');if(a){let b=document.createElement('button');b.textContent='✏️ تعديل أمر العمل';b.onclick=()=>editWO(id);a.prepend(b)}let w=S.workorders.find(x=>x.id===id);if(w){let pct=workOrderCompletion(w),box=document.createElement('div');box.innerHTML=`<h3>نسبة تقدم الـChecklist: ${pct}%</h3><div class="progress"><span style="width:${pct}%"></span></div>`;document.querySelector('#modal h3')?.before(box)}}

const __refreshV12=refresh;refresh=function(){__refreshV12();if(window.sdWO){let cur=sdWO.value;sdWO.innerHTML='<option value="">بدون ربط الآن</option>'+S.workorders.map(w=>`<option value="${w.id}">${esc(w.no)} — ${esc(w.desc||'')}</option>`).join('');sdWO.value=cur}renderSmartHistory()}

CHECK_TEMPLATES.substation=[['قبل البداية','Approved Drawing','مراجعة المخطط المعتمد ونطاق العمل'],['قبل البداية','Safety / Permit','التصريح والسلامة قبل البدء'],['قبل البداية','Material Verification','التحقق من المواد والأكواد قبل التنفيذ'],['التنفيذ','Equipment Inspection','فحص المعدة والبيانات الاسمية والحالة'],['التنفيذ','Installation Evidence','صور التركيب والتوصيلات'],['الفحص','Electrical / Mechanical Checks','الفحوصات الكهربائية والميكانيكية المطلوبة'],['بعد التنفيذ','Inspection / Handover','الفحص والتسليم والإغلاق']];
CHECK_TEMPLATES.metering=[['قبل البداية','Work Order / Meter Data','مراجعة أمر العمل وبيانات العداد'],['قبل البداية','Safety / Isolation','السلامة والعزل عند الحاجة'],['قبل البداية','Material Verification','العداد والملحقات والأكواد'],['التنفيذ','Old Condition Evidence','توثيق الحالة قبل العمل'],['التنفيذ','Meter Installation','التركيب والتوصيلات'],['الفحص','Reading / Seal / Test','القراءة والختم والاختبار'],['بعد التنفيذ','Final Evidence','الصور النهائية والتسليم']];
typeLabel=function(t){let m={excavation:'حفر',cable:'تمديد كابل',backfill:'ردم',substation:'محطات / معدات',metering:'عدادات / قياس',other:'عمل آخر'};return (Array.isArray(t)?t:[t]).map(x=>m[x]||'عمل').join(' + ')};


// ===== V14: crews, safety contacts, dynamic work types, site requirements, SEC visual catalog =====
function daysTo(d){if(!d)return 99999;return Math.ceil((new Date(d+'T23:59:59')-new Date())/86400000)}
function expiryState(p){let ds=[p.iqEnd,p.cidEnd,p.secEnd].filter(Boolean).map(daysTo);if(ds.some(x=>x<0))return 'expired';let w=+p.warnDays||15;if(ds.some(x=>x<=w))return 'warning';return 'valid'}
function expiryBadge(p){let s=expiryState(p);return s==='expired'?'<span class="badge" style="background:#fee2e2;color:#991b1b">منتهي</span>':s==='warning'?'<span class="badge warn">⚠️ تنبيه خلال '+(+p.warnDays||15)+' يوم</span>':'<span class="badge ok">ساري</span>'}
function addCrewPerson(){if(!cpName.value.trim())return alert('اكتب الاسم');S.crewPeople.push({id:uid(),group:cgName.value.trim(),name:cpName.value.trim(),role:cpRole.value,phone:cpPhone.value.trim(),email:cpEmail.value.trim(),iqStart:cpIqStart.value,iqEnd:cpIqEnd.value,cidEnd:cpCidEnd.value,secEnd:cpSecEnd.value,warnDays:+cpWarn.value||15});save();[cpName,cpPhone,cpEmail,cpIqStart,cpIqEnd,cpCidEnd,cpSecEnd].forEach(x=>x.value='');}
function renderCrews(){if(!window.crewBody)return;let q=(crewQ?.value||'').toLowerCase(),g=(crewGroupQ?.value||'').toLowerCase(),st=crewExpiryQ?.value||'';let a=S.crewPeople.filter(p=>(p.name+' '+p.role+' '+p.phone+' '+p.email).toLowerCase().includes(q)&&String(p.group||'').toLowerCase().includes(g)&&(!st||expiryState(p)===st));crewBody.innerHTML=a.map(p=>`<tr><td>${esc(p.group||'—')}</td><td><b>${esc(p.name)}</b><br>${esc(p.role)}</td><td>${esc(p.phone||'—')}<br>${esc(p.email||'')}</td><td>${esc(p.iqStart||'—')} → ${esc(p.iqEnd||'—')}</td><td>${esc(p.cidEnd||'—')}</td><td>${esc(p.secEnd||'—')}</td><td>${expiryBadge(p)}</td><td><button onclick="editCrew('${p.id}')">تعديل</button> <button onclick="deleteCrew('${p.id}')">حذف</button></td></tr>`).join('')||'<tr><td colspan="8" class="empty">لا توجد بيانات.</td></tr>'}
function editCrew(id){let p=S.crewPeople.find(x=>x.id===id);if(!p)return;let name=prompt('الاسم',p.name);if(name===null)return;p.name=name;let phone=prompt('الجوال',p.phone||'');if(phone!==null)p.phone=phone;let email=prompt('الإيميل',p.email||'');if(email!==null)p.email=email;save()}
function deleteCrew(id){if(confirm('حذف هذا الشخص من جروبات التنفيذ؟')){S.crewPeople=S.crewPeople.filter(x=>x.id!==id);save()}}
function addSafetyContact(){if(!scName.value.trim()||(!scPhone.value.trim()&&!scEmail.value.trim()))return alert('اكتب الاسم ورقم الجوال أو الإيميل');S.safetyContacts.push({id:uid(),role:scRole.value,name:scName.value.trim(),phone:scPhone.value.trim(),email:scEmail.value.trim(),section:scSection.value});save();[scName,scPhone,scEmail].forEach(x=>x.value='')}
function renderSafetyContacts(){if(!window.scBody)return;scBody.innerHTML=S.safetyContacts.map(x=>`<tr><td>${esc(x.role)}</td><td><b>${esc(x.name)}</b></td><td>${esc(x.phone||'—')}</td><td>${esc(x.email||'—')}</td><td>${esc(x.section)}</td><td><button onclick="deleteSafetyContact('${x.id}')">حذف</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">لا توجد مصادر/مستلمين بعد.</td></tr>'}
function deleteSafetyContact(id){if(confirm('حذف؟')){S.safetyContacts=S.safetyContacts.filter(x=>x.id!==id);save()}}
function addWorkType(){let n=newWorkType.value.trim();if(!n)return;let id='custom_'+Date.now().toString(36);S.workTypes.push({id,name:n});newWorkType.value='';save()}
function syncWorkTypeOptions(){let selects=[window.wtype].filter(Boolean);selects.forEach(sel=>{let chosen=[...sel.selectedOptions].map(o=>o.value);sel.innerHTML=S.workTypes.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('');[...sel.options].forEach(o=>o.selected=chosen.includes(o.value))});if(window.workTypeChips)workTypeChips.innerHTML=S.workTypes.map(x=>`<span class="pill">${esc(x.name)}</span>`).join('');syncDynamicFiltersV164()}
function openSECCatalog(){window.open('assets/SEC_CATALOGUE.pdf','_blank')}


