S.surveys=S.surveys||[];S.governance=S.governance||[];S.locations=S.locations||[];
if(!S.locations.some(x=>x.city==='جدة'&&x.area==='الشرفية'))S.locations.push({id:uid(),city:'جدة',zone:'وسط جدة',area:'الشرفية',source:'user/map'});
function requiredWOOpts(){return '<option value="">— اختر أمر العمل —</option>'+S.workorders.map(w=>`<option value="${w.id}">${esc(w.no)} — ${esc(w.desc||'')}</option>`).join('')}
function masterLine(w){return w?`${w.city||'—'} | ${w.area||'—'} | ${w.route||w.loc||'—'} | ${w.company||'—'}`:''}
function surveySyncMaster(){let w=S.workorders.find(x=>x.id===svWO.value);svMaster.value=masterLine(w)}
let __surveyNotes=[];function surveyAddNote(){let n=svNote.value.trim();if(!n)return;__surveyNotes.push(n);svNote.value='';svNotes.innerHTML=__surveyNotes.map((x,i)=>`<div>${i+1}. ${esc(x)}</div>`).join('')}
async function saveSurvey(){let w=S.workorders.find(x=>x.id===svWO.value);if(!w)return alert('اختر أمر العمل');let files=[...svFiles.files].map(f=>({name:f.name,size:f.size,type:f.type}));S.surveys.push({id:uid(),wo:w.id,date:svDate.value,expectedLength:+svExpected.value||0,notes:[...__surveyNotes],files});__surveyNotes=[];svNote.value='';svExpected.value='';svFiles.value='';save();toastMsg('تم حفظ الكشفية وربطها بأمر العمل')}
function renderSurveys(){if(!window.svBody)return;let a=S.surveys.filter(s=>{let w=S.workorders.find(x=>x.id===s.wo);let n=+s.expectedLength||0;return(!svFWO.value||s.wo===svFWO.value)&&(!svFArea.value||String(w?.area||'').includes(svFArea.value))&&(!svFMin.value||n>=+svFMin.value)&&(!svFMax.value||n<=+svFMax.value)});svBody.innerHTML=a.map(s=>{let w=S.workorders.find(x=>x.id===s.wo);return`<tr><td><button onclick="openWO('${s.wo}')">${esc(w?.no||'—')}</button></td><td>${esc(w?.city||'—')} / ${esc(w?.area||'—')}</td><td>${esc(s.date||'—')}</td><td>${s.expectedLength||0} م</td><td>${(s.notes||[]).map(esc).join('<br>')||'—'}</td><td>${(s.files||[]).length}</td></tr>`}).join('')||'<tr><td colspan="6" class="empty">لا توجد كشفيات.</td></tr>'}
function govMissing(g){let m=[];if(!g.team)m.push('نموذج فريق العمل');if(!g.program)m.push('البرنامج التشغيلي');if(!g.permits)m.push('التصاريح');if(!g.safety)m.push('إبلاغ السلامة');if(!g.materials)m.push('صرف المواد');return m}
function governanceLoad(){let g=S.governance.find(x=>x.wo===gvWO.value)||{};gvRequested.value=g.requested||'no';gvScheduled.value=g.scheduled||'no';gvDate.value=g.date||'';gvType.value=g.type||'جهد متوسط';gvExecuted.value=g.executed||'no';gvTeam.checked=!!g.team;gvProgram.checked=!!g.program;gvPermits.checked=!!g.permits;gvSafety.checked=!!g.safety;gvMaterials.checked=!!g.materials}
function saveGovernance(){if(!gvWO.value)return alert('اختر أمر العمل');let g=S.governance.find(x=>x.wo===gvWO.value);let d={wo:gvWO.value,requested:gvRequested.value,scheduled:gvScheduled.value,date:gvDate.value,type:gvType.value,executed:gvExecuted.value,team:gvTeam.checked,program:gvProgram.checked,permits:gvPermits.checked,safety:gvSafety.checked,materials:gvMaterials.checked};if(g)Object.assign(g,d);else S.governance.push({id:uid(),...d});save();toastMsg('تم حفظ بيانات الحوكمة')}
function govDays(g){if(!g.date)return 9999;return Math.ceil((new Date(g.date)-new Date())/86400000)}
function renderGovernance(){if(!window.gvBody)return;let a=S.governance.filter(g=>(!gvFReq.value||g.requested===gvFReq.value)&&(!gvFExec.value||g.executed===gvFExec.value)&&(!gvFType.value||String(g.type).includes(gvFType.value))&&(!gvDays.value||(govDays(g)>=0&&govDays(g)<=+gvDays.value)));gvBody.innerHTML=a.map(g=>`<tr><td><button onclick="openWO('${g.wo}')">${esc(woName(g.wo))}</button></td><td>${esc((g.date||'').replace('T',' '))}</td><td>${esc(g.type||'')}</td><td>${g.requested==='yes'?'نعم':'لا'}</td><td>${g.executed==='yes'?'نعم':'لا'}</td><td>${govMissing(g).length?'<span class="badge warn">'+esc(govMissing(g).join('، '))+'</span>':'<span class="badge ok">مكتمل</span>'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">لا توجد سجلات.</td></tr>';renderGovAlerts()}
function renderGovAlerts(){if(!window.govAlerts)return;let a=S.governance.filter(g=>g.date&&g.executed!=='yes'&&govDays(g)>=0&&govDays(g)<=4);govAlerts.innerHTML=a.length?`<div class="permitNotice warn"><b>🔔 لديك ${a.length} أمر عمل بموعد حوكمة/فصل خلال 4 أيام.</b> ${a.filter(g=>govMissing(g).length).length} بها متطلبات غير مكتملة.</div>`:''}
function addLocationArea(){let city=lcCity.value.trim(),area=lcArea.value.trim();if(!city||!area)return alert('اكتب المدينة والحي');if(S.locations.some(x=>x.city===city&&x.area===area))return alert('الحي موجود بالفعل');S.locations.push({id:uid(),city,zone:lcZone.value,area});lcArea.value='';save()}
function renderLocations(){if(!window.lcBody)return;let a=S.locations.filter(x=>(!lcFCity.value||x.city.includes(lcFCity.value))&&(!lcFZone.value||x.zone.includes(lcFZone.value))&&(!lcFArea.value||x.area.includes(lcFArea.value)));lcBody.innerHTML=a.map(x=>`<tr><td>${esc(x.city)}</td><td>${esc(x.zone)}</td><td><b>${esc(x.area)}</b></td><td><button onclick="deleteLocationArea('${x.id}')">حذف</button></td></tr>`).join('')||'<tr><td colspan="4" class="empty">لا توجد أحياء.</td></tr>'}
