function uniqueStreetNames(v){let raw=String(v||'').replace(/\s+/g,' ').split(/(?:—|\||;|،|\n|\r)+/).map(x=>x.trim()).filter(Boolean);let seen=new Set(),out=[];for(let x of raw){let k=x.replace(/[\u064B-\u065F]/g,'').replace(/\s+/g,' ').trim().toLowerCase();if(!seen.has(k)){seen.add(k);out.push(x)}}return out.join(' — ')}
