function kpiBaseV161(){let c=(window.kpiCompany?.value||'').trim().toLowerCase(),f=window.kpiFrom?.value||'',t=window.kpiTo?.value||'';return S.workorders.filter(w=>(!c||String(w.company||'').toLowerCase().includes(c))&&(!f||String(w.assign||w.approvalDate||'')>=f)&&(!t||String(w.assign||w.approvalDate||'')<=t))}
function kpiFilterV161(key){let a=kpiBaseV161();return a.filter(w=>{let p=activePermitForWO(w),g=S.governance.find(x=>x.wo===w.id),sf=S.safetyFiles?.find(x=>x.wo===w.id),ex=(S.executionEvidence||[]).filter(x=>x.wo===w.id);if(key==='all')return true;if(key==='survey')return S.surveys.some(x=>x.wo===w.id);if(key==='permitIssued')return !!p;if(key==='permitExpiring')return !!p&&permitWarn(p);if(key==='permitExpired')return !!p&&permitExpired(p);if(key==='govPending')return !!p&&(!g||g.scheduled!=='yes');if(key==='govSoon')return !!g&&g.date&&dateDiffDays(g.date.slice(0,10))>=0&&dateDiffDays(g.date.slice(0,10))<=4;if(key==='exec')return ex.length>0;if(key==='execGovOnly')return ex.length>0&&(!g||g.executed!=='yes');if(key==='safetyMissing')return !sf||![sf.permit,sf.team,sf.risk,sf.safeWork,sf.brief].every(Boolean);if(key==='completed')return String(w.status||'').includes('مكتمل');return woStageV161(w)===key})}
