 let municipality=one([/(?:البلدية)\s*[:：-]?\s*([\u0600-\u06ff][\u0600-\u06ff\s]{1,45}?)(?=\s+(?:إجمالي|رقم|تاريخ|كمية|الأحياء)|\n|$)/i])||base.municipality;
 let total=one([/(?:إجمالي\s*الطول|اجمالي\s*الطول)\s*[:：-]?\s*([0-9.,]+\s*(?:م|متر|كم|كيلومتر)?)/i])||base.totalLength;
 let damrat=one([/(?:كمية\s*(?:الدمرات|الدمارات|الدمرات)|عدد\s*(?:الدمرات|الدمارات))\s*[:：-]?\s*([0-9.,]+)/i]);
 let issue=one([/(?:تاريخ\s*الإصدار|تاريخ\s*الاصدار)\s*[:：-]?\s*([0-9\/\-.]+)/i]);
 let issueDate=parseDateToken(issue)||base.issueDate;
 // Keep raw route rows for audit, but expose unique street names to filters.
 let routeSegments=[]; let lines=String(text||'').split(/\n+/).map(x=>x.trim()).filter(Boolean);
 for(let ln of lines){if(/شارع|طريق|مسار/i.test(ln)&&/[\u0600-\u06ff]/.test(ln))routeSegments.push(ln)}
