function renderExecutionEvidenceV163(){if(!window.executionEvidenceV16)return;let wo=evWO.value;if(!wo){executionEvidenceV16.innerHTML='<div class="empty">اختر أمر العمل</div>';return}let done=0,approved=0;let cards=EXEC_STAGES_V16.map((stage,i)=>{let e=evRecordV163(wo,stage)||{},complete=!!e.uploadChecked,has=(e.photos||[]).length+(e.videos||[]).length;if(complete)done++;if(e.review==='approved')approved++;return `<div class="notice" style="margin-bottom:10px"><div class="sectionbar"><div><b>${i+1}. ${esc(stageLabelV163(i))}</b><br><span class="muted">${esc(stage)}</span></div><div><span class="badge">📷 ${(e.photos||[]).length}</span><span class="badge">🎥 ${(e.videos||[]).length}</span><span class="badge ${complete?'ok':'warn'}">${complete?'✓ تم الرفع':'ناقص'}</span><span class="badge ${e.review==='approved'?'ok':e.review==='rework'?'warn':''}">${e.review==='approved'?'✓✓ معتمد':e.review==='rework'?'إعادة تصوير':'بانتظار المراجعة'}</span></div></div><div class="row"><div><label>رفع صور — أي مستخدم لديه صلاحية رفع</label><input id="ep_${i}" type="file" accept="image/*" multiple></div><div><label>رفع فيديوهات ≥ 10 ثوانٍ</label><input id="ev_${i}" type="file" accept="video/*" multiple></div><div><button onclick="saveEvidenceV163(${i})">⬆️ رفع Evidence</button></div><div><label><input id="ec_${i}" type="checkbox" style="width:auto" ${complete?'checked':''} onchange="checkEvidenceV163(${i},this.checked)"> ✓ رفعت المطلوب لهذه المرحلة</label></div></div><div class="actions"><button onclick="reviewEvidenceV163(${i},'approved')">✓✓ اعتماد</button><button onclick="reviewEvidenceV163(${i},'rework')">↩️ إعادة تصوير</button></div>${e.lastUploader?`<div class="muted">آخر رفع: ${esc(e.lastUploader)} — ${esc(e.lastUploadDate||'')}</div>`:''}</div>`}).join('');executionEvidenceV16.innerHTML=cards;if(window.executionProgressV163)executionProgressV163.innerHTML=`<div class="notice"><b>تقدم الرفع: ${done}/${EXEC_STAGES_V16.length}</b> — المعتمد: ${approved}/${EXEC_STAGES_V16.length}${done===EXEC_STAGES_V16.length?' — ✅ جاهز للإرسال للمراجعة':' — ناقص '+(EXEC_STAGES_V16.length-done)+' مراحل'}</div>`}
async function saveEvidenceV163(i){let wo=evWO.value,stage=EXEC_STAGES_V16[i],p=document.getElementById('ep_'+i),v=document.getElementById('ev_'+i),e=evRecordV163(wo,stage)||{id:uid(),wo,stage,photos:[],videos:[],uploadChecked:false,review:'pending'};e.photos=e.photos||[];e.videos=e.videos||[];let who=uploaderNameV163();e.photos.push(...[...(p.files||[])].map(f=>({name:f.name,size:f.size,type:f.type,date:new Date().toISOString(),uploadedBy:who})));for(let f of [...(v.files||[])]){let dur=await videoDurationV16(f);if(dur<10){alert(`الفيديو ${f.name} مدته ${dur.toFixed(1)} ثانية — المطلوب 10 ثوانٍ على الأقل`);continue}e.videos.push({name:f.name,size:f.size,type:f.type,duration:dur,date:new Date().toISOString(),uploadedBy:who})}e.lastUploader=who;e.lastUploadDate=new Date().toLocaleString('ar-EG');if(!S.executionEvidence.some(x=>x.id===e.id))S.executionEvidence.push(e);save();renderExecutionEvidenceV163()}
function checkEvidenceV163(i,checked){let wo=evWO.value,stage=EXEC_STAGES_V16[i],e=evRecordV163(wo,stage);if(!e||(!(e.photos||[]).length&&!(e.videos||[]).length)){document.getElementById('ec_'+i).checked=false;return alert('ارفع الصور/الفيديو المطلوب أولاً ثم اعمل ✓ تم الرفع')}e.uploadChecked=checked;e.checkedBy=uploaderNameV163();e.checkedDate=new Date().toISOString();save();renderExecutionEvidenceV163()}
function reviewEvidenceV163(i,state){let e=evRecordV163(evWO.value,EXEC_STAGES_V16[i]);if(!e||!e.uploadChecked)return alert('المرحلة لم يتم تأكيد رفعها بعد');e.review=state;e.reviewDate=new Date().toISOString();save();renderExecutionEvidenceV163()}
renderExecutionEvidenceV16=renderExecutionEvidenceV163;
