 if(box)box.innerHTML=S.siteRequirementDefs.length?S.siteRequirementDefs.map(x=>`<div class="notice"><label><input id="srchk_${x.id}" type="checkbox" style="width:auto" onchange="toggleSiteReqQtyV164('${x.id}')"> ${esc(x.name)}</label>${x.unit!=='بدون كمية'?`<div id="srqtybox_${x.id}" style="display:none"><label>الكمية (${esc(x.unit)})</label><input id="srqty_${x.id}" type="number" step="0.01" min="0"></div>`:''}</div>`).join(''):'<div class="muted">لا توجد متطلبات مضافة. أضفها من إدارة متطلبات الموقع بالأسفل.</div>';
 const master=document.getElementById('siteReqMasterList');if(master)master.innerHTML=S.siteRequirementDefs.map(x=>`<span class="pill">${esc(x.name)}${x.unit!=='بدون كمية'?' — '+esc(x.unit):''}</span>`).join('')||'<span class="muted">لا توجد متطلبات بعد.</span>';
