    const q=(sr?.value||'').trim().toLowerCase();const arr=(S.companies||[]).filter(c=>!q||[c.name,c.code].some(v=>String(v||'').toLowerCase().includes(q)));
    const cards=arr.map(c=>{const w=(S.workorders||[]).filter(x=>x.companyId===c.id),open=w.filter(x=>!['مكتمل','Completed'].includes(String(x.status||''))).length,pending=(S.tasks||[]).filter(t=>t.companyId===c.id&&!t.done).length;return `<div class="companyCard165"><div class="companyHead165">${c.logo?`<img class="companyLogo165" src="${c.logo}">`:'<div class="companyLogo165" style="display:grid;place-items:center;font-size:34px">🏢</div>'}<div><div class="companyName165">${esc(c.name)}</div><div class="muted">${L.code}: ${esc(c.code||'—')}</div></div></div><div class="companyStats165"><div>${L.wo}<b>${w.length}</b></div><div>${L.active}<b>${open}</b></div><div>${L.pending}<b>${pending}</b></div></div><button class="primary" style="width:100%" onclick="selectCompanyV16('${c.id}')">${L.enter}</button></div>`}).join('')||`<div class="empty">${L.empty}</div>`;
