 window.saveCompanyV1610=async function(){let name=document.getElementById('companyNameV1610').value.trim(),code=document.getElementById('companyCodeV1610').value.trim();if(!name)return alert((S.uiLanguage==='en'?'Enter company name':'اكتب اسم الشركة'));let f=document.getElementById('companyLogoV1610').files?.[0],logo=f?await fileDataURL10(f):'';if(editingCompany10){let c=S.companies.find(x=>x.id===editingCompany10);if(c){c.name=name;c.code=code;if(logo)c.logo=logo}}else{S.companies=S.companies||[];S.companies.push({id:'co_'+uid(),name,code,logo,created:new Date().toISOString()})}persist169();closeCompanyModalV1610();renderPortal10()};
