 function currentBlock10(w){let g=(S.governance||[]).find(x=>x.wo===w.id),p=activePermitForWO(w),sf=safetyState10(w),ev=(S.executionEvidence||[]).filter(x=>x.wo===w.id),done=ev.filter(x=>x.uploadChecked).length,re=(S.reinstatement||[]).filter(x=>x.wo===w.id);if(['مكتمل','مغلق','Completed','Closed'].includes(String(w.status||'')))return 'مكتمل/مغلق';if(!p)return 'التصاريح';if(sf!=='مكتمل')return 'السلامة';if(!g||g.requested!=='yes')return 'طلب الحوكمة';if(g.scheduled!=='yes')return 'تحديد موعد الحوكمة';if(g.executed!=='yes')return 'الحوكمة / الفصل';if(done<(EXEC_STAGES_V16?.length||0)){let stages=EXEC_STAGES_V16||[],missing=stages.find(s=>!(S.executionEvidence||[]).find(x=>x.wo===w.id&&x.stage===s&&x.uploadChecked));return missing||'التنفيذ'}if(re.some(x=>!['مكتمل','تم','Completed','Done'].includes(String(x.status||''))))return 'إعادة الوضع';if(re.length===0&&Object.keys(w.siteReq||{}).length)return 'إعادة الوضع';return 'جاهز للإغلاق'}
