 window.renderReportFieldCatalogV1610=function(){let q=(document.getElementById('reportFieldSearchV1610')?.value||'').toLowerCase(),sel=new Set(S.reportBuilderV1610.selected||[]),fs=allFields10().filter(f=>!q||(f.label+' '+f.group+' '+f.key).toLowerCase().includes(q)),groups={};fs.forEach(f=>(groups[f.group]??=[]).push(f));let box=document.getElementById('reportFieldCatalogV1610');if(box)box.innerHTML=Object.entries(groups).map(([g,a])=>`<div class="reportFieldGroupV1610"><h4>${esc(g)}</h4>${a.map(f=>`<label class="reportFieldV1610"><input type="checkbox" ${sel.has(f.key)?'checked':''} onchange="toggleReportFieldV1610('${f.key}',this.checked)"><span>${esc(f.label)}</span></label>`).join('')}</div>`).join('');let gb=document.getElementById('reportGroupByV1610');if(gb){let old=gb.value;gb.innerHTML='<option value="">بدون تجميع</option>'+allFields10().map(f=>`<option value="${f.key}">${esc(f.label)}</option>`).join('');gb.value=old}}
 window.toggleReportFieldV1610=function(k,on){let a=new Set(S.reportBuilderV1610.selected||[]);on?a.add(k):a.delete(k);S.reportBuilderV1610.selected=[...a];persist169()};
