 window.renderReportConditionsV1610=function(){let box=document.getElementById('reportConditionsV1610');if(!box)return;let fs=allFields10();box.innerHTML=(S.reportBuilderV1610.conditions||[]).map((c,i)=>`<div class="reportConditionV1610"><select onchange="updateReportConditionV1610(${i},'field',this.value)">${fs.map(f=>`<option value="${f.key}" ${f.key===c.field?'selected':''}>${esc(f.label)}</option>`).join('')}</select><select onchange="updateReportConditionV1610(${i},'op',this.value)"><option value="contains" ${c.op==='contains'?'selected':''}>يحتوي</option><option value="eq" ${c.op==='eq'?'selected':''}>=</option><option value="ne" ${c.op==='ne'?'selected':''}>≠</option><option value="gt" ${c.op==='gt'?'selected':''}>&gt;</option><option value="gte" ${c.op==='gte'?'selected':''}>≥</option><option value="lt" ${c.op==='lt'?'selected':''}>&lt;</option><option value="lte" ${c.op==='lte'?'selected':''}>≤</option><option value="empty" ${c.op==='empty'?'selected':''}>فارغ</option><option value="notempty" ${c.op==='notempty'?'selected':''}>غير فارغ</option></select><input value="${esc(c.value||'')}" oninput="updateReportConditionV1610(${i},'value',this.value)" placeholder="القيمة"><button onclick="removeReportConditionV1610(${i})">✕</button></div>`).join('')||'<div class="muted">لا توجد شروط. التقرير سيشمل كل المعاملات داخل الشركة الحالية.</div>'}
 function matchCond10(val,c){let a=String(val??'').toLowerCase(),b=String(c.value??'').toLowerCase(),an=parseFloat(val),bn=parseFloat(c.value);if(c.op==='contains')return a.includes(b);if(c.op==='eq')return a===b;if(c.op==='ne')return a!==b;if(c.op==='empty')return a==='';if(c.op==='notempty')return a!=='';if(!Number.isNaN(an)&&!Number.isNaN(bn)){if(c.op==='gt')return an>bn;if(c.op==='gte')return an>=bn;if(c.op==='lt')return an<bn;if(c.op==='lte')return an<=bn}return false}
