 function canCreate(a,teamId,targetRole){if(root(a))return true;if(!a||a.companyId!==cid()||a.teamId!==teamId)return false;let t=teams().find(x=>x.id===teamId);let manager=t?.managerId===a.id||a.isDepartmentManager1620;let delegated=(a.permissions||[]).includes('people.manage')||(a.permissions||[]).includes('access.delegate');if(!manager&&!delegated&&titleRank(a)<25)return false;let fake={role:targetRole,accessScope:'assigned'};return titleRank(fake)<titleRank(a)}
