(function(){
  const baseClose = window.closeModal || (typeof closeModal==='function'?closeModal:null);
  window.closeSecPdf1626=function(){
    const bg=document.getElementById('modalbg');
    const box=document.getElementById('modal');
    if(box){ box.querySelectorAll('iframe').forEach(f=>{try{f.src='about:blank'}catch(e){}}); box.innerHTML=''; }
    if(bg){ bg.style.display='none'; bg.classList.remove('open'); }
    document.body.style.overflow='';
    try{ if(typeof go==='function') go('materials'); else document.getElementById('materials')?.classList.add('active'); }catch(e){}
  };
  window.closeModal=function(){
    const box=document.getElementById('modal');
    if(box?.querySelector('iframe[src*="SEC_CATALOGUE.pdf"]')) return window.closeSecPdf1626();
    if(baseClose) return baseClose();
    const bg=document.getElementById('modalbg'); if(bg) bg.style.display='none';
  };
  window.materialView=function(i){
    const m=S.materials?.[i]; if(!m)return;
    const pp=window.secPrintedPage1614?.(m.catalogPage);
    const pdf=m.catalogPage?`<div class="notice"><b>مرجع الصفحة:</b> صفحة عارض PDF = <b>${m.catalogPage}</b>${pp?` — الرقم المطبوع = <b>${pp}</b>`:''}</div><iframe class="pdfbox" style="height:70vh" src="assets/SEC_CATALOGUE.pdf#page=${m.catalogPage}"></iframe>`:'';
    showModal(`<div style="position:sticky;top:-18px;z-index:100;background:#fff;padding:12px 0;border-bottom:1px solid #ddd;display:flex;justify-content:space-between;align-items:center;gap:10px"><b>📖 ${esc(m.code)} — كتالوج SEC</b><button class="danger" style="font-size:16px;min-width:150px" onclick="closeSecPdf1626()">✕ إغلاق PDF</button></div><p><b>التوصيف:</b> ${esc(m.description)}</p><p><b>الوحدة:</b> ${esc(m.unit||'—')} &nbsp; <b>SDMS:</b> ${esc(m.sdms||'—')}</p><p><b>الاستخدام:</b> ${esc(m.usage||'—')}</p>${m.image?`<img src="${m.image}" style="max-width:100%;max-height:300px">`:''}${pdf||'<div class="notice">لا يوجد مرجع صفحة مرتبط بهذا الكود.</div>'}<div class="actions"><button class="primary" onclick="closeSecPdf1626()">↩️ إغلاق والعودة للمواد والأكواد</button></div>`);
  };
  document.addEventListener('keydown',function(e){if(e.key==='Escape'&&document.getElementById('modal')?.querySelector('iframe[src*="SEC_CATALOGUE.pdf"]')){e.preventDefault();window.closeSecPdf1626();}},true);
  document.getElementById('modalbg')?.addEventListener('click',function(e){if(e.target===this&&document.getElementById('modal')?.querySelector('iframe[src*="SEC_CATALOGUE.pdf"]'))window.closeSecPdf1626();},true);
})();

