/* V16.31 — Governance work-order timeline, readiness and flexible day filters */
(function(){
  const labelMap={needs_schedule:'محتاج تحديد موعد',scheduled:'تم تحديد الموعد',postponed:'تم التأجيل',cancelled:'ملغي',rescheduled:'موعد جديد',executed:'تم التنفيذ / الفصل'};
  window.govEventLabel1615=function(s){return labelMap[s]||s||'—'};
  function readiness1631(){
    const box=document.getElementById('gvReadiness1631'); if(!box)return;
    const ids=['gvTeam','gvProgram','gvPermits','gvSafety','gvMaterials'];
    const done=ids.filter(id=>document.getElementById(id)?.checked).length;
    const pct=Math.round(done/ids.length*100);
    box.innerHTML=`<b>جاهزية أمر العمل: ${done}/${ids.length} (${pct}%)</b> — ${done===ids.length?'✅ جاهز للتنفيذ':'⏳ توجد بنود قبل التنفيذ'}`;
  }
  ['gvTeam','gvProgram','gvPermits','gvSafety','gvMaterials'].forEach(id=>document.getElementById(id)?.addEventListener('change',readiness1631));
  const oldLoad=window.governanceLoad;
  window.governanceLoad=function(){oldLoad();readiness1631(); if(typeof renderGovHistory1615==='function')renderGovHistory1615()};
  window.addGovernanceEvent1615=function(){
    if(!gvWO.value)return alert('اختر أمر العمل أولاً');
    let g=S.governance.find(x=>x.wo===gvWO.value);
    if(!g){saveGovernance();g=S.governance.find(x=>x.wo===gvWO.value)} if(!g)return;
    const status=gvEventStatus.value,date=gvEventDate.value,reason=gvEventReason.value.trim();
    if(['scheduled','postponed','rescheduled','executed'].includes(status)&&!date)return alert('حدد تاريخ ووقت الحركة');
    g.scheduleHistory=g.scheduleHistory||[];
    g.scheduleHistory.push({id:uid(),status,date,reason,createdAt:new Date().toISOString()});
    if(status==='needs_schedule'||status==='cancelled'){g.scheduled='no';g.date=''; if(status==='needs_schedule')g.requested='yes'}
    else if(status==='executed'){g.executed='yes';g.scheduled='yes';if(date)g.date=date}
    else {g.scheduled='yes';g.date=date}
    gvRequested.value=g.requested||'no';gvScheduled.value=g.scheduled||'no';gvDate.value=g.date||'';gvExecuted.value=g.executed||'no';
    gvEventDate.value='';gvEventReason.value='';save();renderGovHistory1615();renderGovernance();if(typeof renderPriorityMonitor1615==='function')renderPriorityMonitor1615();toastMsg('تم تسجيل حركة الحوكمة على أمر العمل');
  };
  window.renderGovernance=function(){
    if(!window.gvBody)return;
    const minEl=document.getElementById('gvDaysMin'),maxEl=document.getElementById('gvDays');
    const min=minEl&&minEl.value!==''?Number(minEl.value):null,max=maxEl&&maxEl.value!==''?Number(maxEl.value):null;
    let a=S.governance.filter(g=>{
      if(gvFReq.value&&g.requested!==gvFReq.value)return false;
      if(gvFExec.value&&g.executed!==gvFExec.value)return false;
      if(gvFType.value&&!String(g.type||'').includes(gvFType.value))return false;
      const d=govDays(g);
      if(min!==null&&(d===''||d<min))return false;
      if(max!==null&&(d===''||d>max))return false;
      return true;
    });
    gvBody.innerHTML=a.map(g=>{const d=govDays(g),status=(typeof currentGovStatus1615==='function'?currentGovStatus1615(g):(g.executed==='yes'?'تم التنفيذ':g.scheduled==='yes'?'موعد محدد':'محتاج تحديد موعد'));return `<tr><td><button onclick="openWO('${g.wo}')">${esc(woName(g.wo))}</button></td><td>${esc((g.date||'').replace('T',' '))}${d!==''?`<br><small>المتبقي: ${d} يوم</small>`:''}</td><td>${esc(g.type||'')}<br><small>${esc(status)}</small></td><td>${g.requested==='yes'?'نعم':'لا'}</td><td>${g.executed==='yes'?'نعم':'لا'}</td><td>${govMissing(g).length?'<span class="badge warn">'+esc(govMissing(g).join('، '))+'</span>':'<span class="badge ok">مكتمل</span>'}</td></tr>`}).join('')||'<tr><td colspan="6" class="empty">لا توجد سجلات مطابقة للفلاتر.</td></tr>';
    renderGovAlerts();
  };
  readiness1631();
})();

/* V16.32 — unified SEC PDF viewer: every Materials/Codes PDF route stays inside app */
(function(){
  function ensureSecPdfViewer1632(){
    let x=document.getElementById('secPdfOverlay1632');
    if(x) return x;
    x=document.createElement('div');
    x.id='secPdfOverlay1632';
    x.setAttribute('role','dialog');
    x.setAttribute('aria-modal','true');
    x.style.cssText='position:fixed;inset:0;z-index:2147483646;background:rgba(3,18,30,.94);display:none;padding:8px;box-sizing:border-box';
    x.innerHTML=`<div style="height:100%;width:100%;background:#fff;border-radius:12px;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 20px 60px #0008">
      <div style="position:relative;z-index:2;flex:0 0 auto;min-height:58px;padding:8px 12px;border-bottom:2px solid #d8dee6;display:flex;align-items:center;justify-content:space-between;gap:10px;background:#fff">
        <div><b id="secPdfTitle1632">📖 كتالوج SEC — المواد والأكواد</b><div style="font-size:12px;color:#657080">زر الإغلاق تابع للبرنامج ويظل خارج ملف PDF.</div></div>
        <div style="display:flex;gap:8px;align-items:center">
          <button type="button" id="secPdfBack1632" style="padding:10px 14px;font-weight:700">↩ العودة للمواد والأكواد</button>
          <button type="button" id="secPdfX1632" class="danger" aria-label="إغلاق PDF" style="padding:10px 18px;font-size:18px;font-weight:900;min-width:135px">✕ إغلاق PDF</button>
        </div>
      </div>
      <iframe id="secPdfFrame1632" title="SEC Catalogue PDF" style="display:block;width:100%;flex:1;min-height:0;border:0;background:#e9edf2"></iframe>
    </div>`;
    document.body.appendChild(x);
    x.querySelector('#secPdfX1632').onclick=window.closeSecPdf1632;
    x.querySelector('#secPdfBack1632').onclick=window.closeSecPdf1632;
    return x;
  }
  window.closeSecPdf1632=function(){
    const x=document.getElementById('secPdfOverlay1632');
    if(!x) return;
    const f=document.getElementById('secPdfFrame1632');
    if(f) f.src='about:blank';
    x.style.display='none';
    document.body.style.overflow='';
  };
  window.openSecPdf1632=function(page){
    const x=ensureSecPdfViewer1632();
    const n=parseInt(page,10);
    const title=document.getElementById('secPdfTitle1632');
    title.textContent=n>0?'📖 كتالوج SEC — صفحة PDF '+n:'📖 كتالوج SEC — المواد والأكواد';
    document.getElementById('secPdfFrame1632').src='assets/SEC_CATALOGUE.pdf'+(n>0?'#page='+n:'');
    x.style.display='block';
    document.body.style.overflow='hidden';
    setTimeout(()=>document.getElementById('secPdfX1632')?.focus(),0);
  };
  // Override BOTH real entry paths used by Materials/Codes.
  window.openSECCatalog=function(){ window.openSecPdf1632(); };
  window.openSecPdfPage1614=function(page){ window.openSecPdf1632(page); };
  // Compatibility with the previous viewer close function.
  window.closeSecPdf1628=function(){ window.closeSecPdf1632(); };
  document.addEventListener('keydown',function(e){
    if(e.key==='Escape' && document.getElementById('secPdfOverlay1632')?.style.display==='block'){
      e.preventDefault(); e.stopPropagation(); window.closeSecPdf1632();
    }
  },true);
})();

