 window.openPermissionCenter1633=function(personId=''){ensure();let a=actor(),target=people().find(x=>x.id===personId)||a;showModal(`<div class="sectionbar"><div><h2>🔐 التفويضات وطلبات الصلاحيات</h2><div class="muted">Claim Permission أو Delegate Permission بمدة محددة وسجل تدقيق كامل.</div></div><button onclick="closeModal()">✕</button></div><div class="progrid"><div><label>الشخص</label><select id="pdTarget33">${people().map(p=>`<option value="${p.id}" ${p.id===target?.id?'selected':''}>${esc33(p.name)} — ${esc33(p.role||'')}</option>`).join('')}</select></div><div><label>الصلاحية</label><select id="pdPerm33">${PERMS.map(x=>`<option value="${x[0]}">${x[1]}</option>`).join('')}</select></div><div><label>من</label><input id="pdFrom33" type="date" value="${now().slice(0,10)}"></div><div><label>إلى</label><input id="pdTo33" type="date"></div></div><label>السبب</label><textarea id="pdReason33" placeholder="إجازة HR / تغطية مؤقتة / احتياج عمل..."></textarea><div class="actions"><button class="primary" onclick="requestPermClaim1633()">🙋 Claim للصلاحية</button><button onclick="delegatePerm1633()">🤝 تفويض مباشر</button></div><hr><h3>السجل</h3><div class="tablewrap"><table><thead><tr><th>النوع</th><th>المستفيد</th><th>الصلاحية</th><th>الفترة</th><th>الحالة</th><th></th></tr></thead><tbody>${S.permissionDelegations1633.filter(x=>x.companyId===cid()).slice().reverse().map(x=>`<tr><td>${x.mode}</td><td>${esc33(people().find(p=>p.id===x.targetId)?.name||'—')}</td><td>${esc33(PERMS.find(p=>p[0]===x.permission)?.[1]||x.permission)}</td><td>${x.from||'—'} → ${x.to||'—'}</td><td>${x.status}</td><td>${x.status==='pending'?`<button onclick="approvePerm1633('${x.id}')">اعتماد</button> <button onclick="rejectPerm1633('${x.id}')">رفض</button>`:x.status==='active'?`<button onclick="revokePerm1633('${x.id}')">إلغاء</button>`:''}</td></tr>`).join('')}</tbody></table></div>`)};
 window.requestPermClaim1633=function(){ensure();let a=actor(),target=document.getElementById('pdTarget33').value;if(a&&target!==a.id&&rank(a)<80)return toast('Claim يكون لنفسك، أو يديره مدير مشروع فما فوق','bad');let x={id:uid(),companyId:cid(),mode:'Claim',requesterId:a?.id||'super_admin',targetId:target,permission:document.getElementById('pdPerm33').value,from:document.getElementById('pdFrom33').value,to:document.getElementById('pdTo33').value,reason:document.getElementById('pdReason33').value.trim(),status:'pending',createdAt:now()};S.permissionDelegations1633.push(x);audit('Claim صلاحية',x.permission);save33();closeModal();toast('تم إرسال طلب الصلاحية للاعتماد','ok')};
 window.delegatePerm1633=function(){ensure();let a=actor(),t=people().find(x=>x.id===document.getElementById('pdTarget33').value),perm=document.getElementById('pdPerm33').value;if(!a||(!hasPerm(a,perm)&&rank(a)<80))return toast('لا يمكنك تفويض صلاحية لا تملكها','bad');if(t&&rank(t)>=rank(a)&&rank(a)<80)return toast('التفويض متاح لمن هم أدنى في التسلسل الإداري','bad');let x={id:uid(),companyId:cid(),mode:'Delegate',requesterId:a.id,ownerId:a.id,targetId:t.id,permission:perm,from:document.getElementById('pdFrom33').value,to:document.getElementById('pdTo33').value,reason:document.getElementById('pdReason33').value.trim(),preExisting:(t.permissions||[]).includes(perm),status:'active',createdAt:now(),approvedAt:now()};S.permissionDelegations1633.push(x);t.permissions=t.permissions||[];if(!t.permissions.includes(perm))t.permissions.push(perm);notifyManagers(t,`${a.name} فوّض ${t.name} بصلاحية ${PERMS.find(p=>p[0]===perm)?.[1]||perm}`);audit('تفويض صلاحية',`${a.name} → ${t.name}: ${perm}`);save33();closeModal();toast('تم التفويض وإخطار المستويات الأعلى','ok')};
 window.approvePerm1633=function(id){ensure();let x=S.permissionDelegations1633.find(q=>q.id===id),a=actor(),t=people().find(p=>p.id===x?.targetId),owner=people().find(p=>hasPerm(p,x?.permission));if(!x||x.status!=='pending')return;if(a&&!(hasPerm(a,x.permission)||rank(a)>rank(owner)||rank(a)>=80))return toast('الاعتماد لصاحب الصلاحية أو مدير أعلى','bad');x.status='active';x.approvedBy=a?.id||'super_admin';x.approvedAt=now();t.permissions=t.permissions||[];if(!t.permissions.includes(x.permission))t.permissions.push(x.permission);notifyManagers(t,`${a?.name||'Super Admin'} اعتمد صلاحية ${x.permission} لـ ${t.name}`);audit('اعتماد Claim صلاحية',`${t.name}: ${x.permission}`);save33();openPermissionCenter1633(t.id)};
 window.rejectPerm1633=function(id){let x=S.permissionDelegations1633.find(q=>q.id===id);if(!x)return;x.status='rejected';x.closedAt=now();audit('رفض Claim صلاحية',x.permission);save33();closeModal()};
 window.revokePerm1633=function(id){let x=S.permissionDelegations1633.find(q=>q.id===id),t=people().find(p=>p.id===x?.targetId);if(!x||!t)return;x.status='revoked';x.closedAt=now();let still=S.permissionDelegations1633.some(q=>q.id!==x.id&&q.targetId===t.id&&q.permission===x.permission&&q.status==='active');if(!still&&!x.preExisting)t.permissions=(t.permissions||[]).filter(k=>k!==x.permission);audit('إلغاء تفويض صلاحية',`${t.name}: ${x.permission}`);save33();closeModal()};
 function expire(){ensure();let d=now().slice(0,10),changed=false;S.permissionDelegations1633.forEach(x=>{if(x.status==='active'&&x.to&&x.to<d){x.status='expired';let t=people().find(p=>p.id===x.targetId);let still=S.permissionDelegations1633.some(q=>q.id!==x.id&&q.targetId===x.targetId&&q.permission===x.permission&&q.status==='active'&&(!q.to||q.to>=d));if(t&&!still&&!x.preExisting)t.permissions=(t.permissions||[]).filter(k=>k!==x.permission);changed=true}});if(changed)save33()}
 // Add HR delegation tab and profile buttons after the existing HR renderer.
