 window.saveHRItem1634=function(id){init();let p=ppl().find(x=>x.id===id),t=document.getElementById('hiType34').value;if(t==='data'){let label=document.getElementById('hiLabel34').value.trim();if(!label)return toast('اسم البيان مطلوب','bad');p.hrExtraData1634.push({id:uid(),label,value:document.getElementById('hiValue34').value.trim(),expiry:document.getElementById('hiExpiry34').value,at:new Date().toISOString()})}else if(t==='note'){let text=document.getElementById('hiNote34').value.trim();if(!text)return toast('الملاحظة مطلوبة','bad');p.hrNotes1634.push({id:uid(),text,at:new Date().toISOString()})}else{let type=document.getElementById('hiAccType34').value.trim(),to=document.getElementById('hiAccTo34').value;if(!type||!to)return toast('اسم التعميد وتاريخ النهاية مطلوبان','bad');p.accreditations1633.push({id:uid(),type,issuer:document.getElementById('hiAccIssuer34').value.trim(),no:document.getElementById('hiAccNo34').value.trim(),from:document.getElementById('hiAccFrom34').value,to,scope:document.getElementById('hiAccScope34').value.trim()})}S.hrAudit1627.unshift({id:uid(),companyId:cid(),action:'تحديث ملف HR',details:p.name+' — '+t,at:new Date().toISOString()});save34();closeModal();openHRProfile1633(id)};
 const oldProfile=window.openHRProfile1633;
 window.openHRProfile1633=function(id){init();let p=ppl().find(x=>x.id===id);if(!p)return oldProfile?.(id);let iq=st(p.iqamaExpiry),ss=st(p.secIdExpiry,'sec',p),aa=accExpiry(p);showModal(`<div class="sectionbar"><div><h2>👤 ${E(p.name)}</h2><div class="muted">ملف HR المركزي</div></div><button onclick="closeModal()">✕</button></div><div class="progrid"><div><b>الجوال</b><br>${E(p.phone||'—')}</div><div><b>Email</b><br>${E(p.email||'—')}</div><div><b>الجنسية</b><br>${E(p.nationality||'—')}</div><div><b>المهنة في الإقامة</b><br>${E(p.iqamaProfession||'—')}</div><div><b>المهنة الفعلية</b><br>${E(p.actualProfession||'—')}</div><div><b>رقم الإقامة</b><br>${E(p.iqamaNo||'—')}</div><div><b>انتهاء الإقامة</b><br>${E(p.iqamaExpiry||'—')} — ${badge(iq)}</div><div><b>SEC ID</b><br>${E(p.secId||'—')}</div><div><b>انتهاء SEC ID</b><br>${E(p.secIdExpiry||'—')} — ${badge(ss)}</div><div><b>الكفالة</b><br>${E(p.sponsor||'—')}</div></div><div class="actions"><button class="primary" onclick="openHRAddItem1634('${id}')">＋ إضافة بيانات / ملاحظة / تعميد</button><button onclick="openPermissionCenter1633('${id}')">🔐 الصلاحيات والتفويض</button></div><h3>التعاميد</h3>${(p.accreditations1633||[]).map(x=>`<div class="card"><b>${E(x.type||'تعميد')}</b> — ${E(x.issuer||'—')} ${badge(st(x.to))}<br>${E(x.no||'')} ${E(x.scope||'')}<br><small>${E(x.from||'—')} → <b>${E(x.to||'—')}</b></small></div>`).join('')||'<div class="muted">لا توجد تعميدات.</div>'}<h3>بيانات إضافية</h3>${p.hrExtraData1634.map(x=>`<div class="card"><b>${E(x.label)}</b>: ${E(x.value||'—')} ${x.expiry?' — '+E(x.expiry)+' '+badge(st(x.expiry)):''}</div>`).join('')||'<div class="muted">لا توجد.</div>'}<h3>ملاحظات الشخص</h3>${p.hrNotes1634.slice().reverse().map(x=>`<div class="card">${E(x.text)}<br><small>${E(x.at)}</small></div>`).join('')||'<div class="muted">لا توجد.</div>'}`)};
 window.submitSecReturn1634=function(id){init();let p=ppl().find(x=>x.id===id);if(!p)return;showModal(`<div class="sectionbar"><h2>↩ إرجاع كارت الأمن الصناعي — ${E(p.name)}</h2><button onclick="closeModal()">✕</button></div><label>نموذج الإرجاع *</label><input id="secReturnFile34" type="file" accept="image/*,.pdf"><label>ملاحظة</label><textarea id="secReturnNote34"></textarea><div class="actions"><button class="primary" onclick="saveSecReturn1634('${id}')">حفظ نموذج الإرجاع</button></div>`)};
