 window.openHRControl1634=function(mode='people'){init();let title={people:'الأفراد والفلترة',iqama:'ركن الإقامات',acc:'ركن التعميدات',sec:'ركن كروت الأمن الصناعي',alerts:'التنبيهات'}[mode]||'HR';if(mode==='alerts'){let a=alerts();showModal(`<div class="sectionbar"><div><h2>🔔 HR — التنبيهات</h2><div class="muted">تنبيه افتراضي قبل الانتهاء بـ ${S.hrAlertDays1634} يوم.</div></div><button onclick="closeModal()">✕</button></div><div class="progrid"><div><label>مدة التنبيه بالأيام</label><input id="alertDays34" type="number" min="1" value="${S.hrAlertDays1634}"></div></div><button onclick="S.hrAlertDays1634=+document.getElementById('alertDays34').value||15;save34();openHRControl1634('alerts')">حفظ المدة</button><div class="tablewrap"><table><thead><tr><th>الشخص</th><th>رقم الإقامة</th><th>العنصر</th><th>الانتهاء</th><th>المتبقي</th><th>الحالة</th></tr></thead><tbody>${a.map(x=>`<tr><td><button class="linklike" onclick="openHRProfile1633('${x.p.id}')">${E(x.p.name)}</button></td><td>${E(x.p.iqamaNo||'—')}</td><td>${E(x.type)}</td><td>${E(x.d)}</td><td>${x.n<0?'منتهي منذ '+Math.abs(x.n)+' يوم':x.n+' يوم'}</td><td>${badge(x.s)}</td></tr>`).join('')||'<tr><td colspan="6">لا توجد تنبيهات حالياً.</td></tr>'}</tbody></table></div>`);return}showModal(`<div class="sectionbar"><div><h2>👥 HR — ${title}</h2><div class="muted">🟢 ساري · 🟠 قرب الانتهاء · 🔴 منتهي · 🟡 تم الإرجاع</div></div><button onclick="closeModal()">✕</button></div><input id="hrSearch34" placeholder="فلتر بالاسم / المهنة / الإقامة / الجنسية / المسمى..." oninput="document.getElementById('hrRows34').innerHTML=hrRows1634('${mode}',this.value)"><div class="tablewrap"><table><thead><tr><th>الشخص</th><th>المهنة</th><th>رقم الإقامة</th><th>الإقامة</th><th>التعميد</th><th>SEC ID</th><th>إجراء</th></tr></thead><tbody id="hrRows34">${rows(mode)}</tbody></table></div>`)};
